package leetcode.medium;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OnlineStockSpanTest {

    @Test
    public void calculateSpans_EmptyArray_ReturnsEmptyArray() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] result = solution.calculateSpans(new int[0]);
        assertTrue(result.length == 0);
    }

    @Test
    public void calculateSpans_SingleElementArray_ReturnsOneElementArray() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {1};
        int[] result = solution.calculateSpans(prices);
        assertEquals(1, result[0]);
    }

    @Test
    public void calculateSpans_MultipleElementsArray_ReturnsCorrectSpans() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {100, 80, 75, 60, 95};
        int[] result = solution.calculateSpans(prices);
        assertEquals(1, result[0]);
        assertEquals(2, result[1]);
        assertEquals(1, result[2]);
        assertEquals(4, result[3]);
        assertEquals(1, result[4]);
    }

    @Test
    public void next_EmptyArray_ThrowsNoException() {
        OnlineStockSpan solution = new OnlineStockSpan();
        assertFalse(solution.next(new int[0]).hasNext());
    }

    @Test
    public void next_SingleElementArray_ReturnsNonZeroValue() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {1};
        assertTrue(solution.next(prices).next().getValue() > 0);
    }

    @Test
    public void next_MultipleElementsArray_ReturnsCorrectPrice() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {100, 80, 75, 60, 95};
        assertTrue(solution.next(prices).next().getValue() == prices[0]);
        assertTrue(solution.next(prices).next().getValue() == prices[1]);
        assertTrue(solution.next(prices).next().getValue() == prices[2]);
        assertTrue(solution.next(prices).next().getValue() == prices[3]);
        assertTrue(solution.next(prices).next().getValue() == prices[4]);
    }

    @Test
    public void next_DuplicateValues_ReturnsCorrectPrice() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {100, 80, 75, 60, 95};
        assertTrue(solution.next(prices).next().getValue() == prices[0]);
        assertTrue(solution.next(prices).next().getValue() == prices[0]);
    }

}

